 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable shape(int color,int stroke,float radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),stroke);return d;}
 void selected(Button b,boolean active){b.setBackground(shape(active?0xff204c42:0xff1b2d43,active?MINT:EDGE,10));b.setTextColor(active?0xffb9f3e2:TEXT);}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 TextView text(String value,float size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(2),1);return t;}
 private TextView label(String key,String value,float size,int color){TextView t=text(value,size,color);labels.put(key,t);return t;}
 void say(String key,String value){TextView t=labels.get(key);if(t!=null&&!value.contentEquals(t.getText()))t.setText(value);}
 void gap(LinearLayout parent,int height){View v=new View(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(height)));}
 private void heading(LinearLayout p,String title,String subtitle){TextView t=text(title,23,TEXT);t.setTypeface(null,Typeface.BOLD);p.addView(t);p.addView(text(subtitle,13,MUTED));gap(p,18);}
 LinearLayout card(LinearLayout parent,String title,String helper){
  LinearLayout c=vertical();c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(shape(CARD,EDGE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(16);parent.addView(c,lp);
  if(title!=null){TextView h=text(title,17,TEXT);h.setTypeface(null,Typeface.BOLD);c.addView(h);}if(helper!=null){gap(c,5);c.addView(text(helper,12,MUTED));gap(c,10);}return c;
 }
 Button button(String title,Runnable action,boolean device){Button b=new Button(this);b.setText(title);b.setTextSize(13);b.setAllCaps(false);b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setPadding(dp(10),dp(8),dp(10),dp(8));selected(b,false);b.setOnClickListener(v->action.run());if(device)deviceButtons.add(b);return b;}
 void addButton(LinearLayout p,Button b){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(9);p.addView(b,lp);}
 void pair(LinearLayout p,Button a,Button b){LinearLayout r=row();LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,-2,1);l.rightMargin=dp(4);r.addView(a,l);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,-2,1);rp.leftMargin=dp(4);r.addView(b,rp);gap(p,9);p.addView(r);}
 private final class Field {
  final EditText input;boolean dirty=false,setting=false;
  Field(LinearLayout parent,String key,String title,String hint,boolean number){
   gap(parent,14);parent.addView(text(title,12,MUTED));input=new EditText(MainActivity.this);input.setSingleLine(true);input.setTextSize(16);input.setTextColor(TEXT);input.setHintTextColor(0xff73869d);input.setHint(hint);input.setPadding(dp(12),dp(10),dp(12),dp(10));input.setBackground(shape(0xff0b1828,0xff3a5069,9));input.setContentDescription(title);input.setInputType(number?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);
   LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(6);parent.addView(input,lp);fields.put(key,this);
   input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!setting)dirty=true;}public void afterTextChanged(Editable s){}});
  }
  String value(){return input.getText().toString().trim();}
  void fromBoard(String value){if(!dirty){setting=true;input.setText(value);setting=false;}}
 }
 private void build(){
  root=vertical();root.setBackgroundColor(BG);root.setPadding(dp(16),dp(12),dp(16),dp(8));
  if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(dp(16)+i.left,dp(8)+i.top,dp(16)+i.right,dp(8)+i.bottom);return insets;});else root.setFitsSystemWindows(true);
  LinearLayout top=row();TextView mark=text("TL",18,BG);mark.setTypeface(null,Typeface.BOLD);mark.setGravity(Gravity.CENTER);mark.setBackground(shape(MINT,MINT,12));top.addView(mark,new LinearLayout.LayoutParams(dp(43),dp(43)));
  LinearLayout name=vertical();TextView title=text("TRUCKLOAD",18,TEXT);title.setTypeface(null,Typeface.BOLD);name.addView(title);name.addView(label("connection","Not connected",11,MUTED));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.leftMargin=dp(12);top.addView(name,np);
  connectButton=button("Connect",this::connectPressed,false);connectButton.setId(101);top.addView(connectButton,new LinearLayout.LayoutParams(dp(108),-2));root.addView(top);gap(root,15);
  for(int r=0;r<2;r++){LinearLayout tabs=row();for(int c=0;c<3;c++){final int index=r*3+c;Button b=button(tabNames[index],()->showTab(index),false);b.setId(200+index);b.setTextSize(12);navButtons.add(b);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(2),dp(2),dp(2),dp(2));tabs.addView(b,lp);}root.addView(tabs);}
  gap(root,14);scroll=new ScrollView(this);scroll.setFillViewport(false);body=vertical();scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView foot=label("footer","Sensor input off",11,MUTED);foot.setPadding(0,dp(6),0,0);root.addView(foot);setContentView(root);
  pages.add(overview());pages.add(trailers());pages.add(lighting());pages.add(colors());pages.add(display());pages.add(gps());
 }
 void showTab(int index){currentTab=index;body.removeAllViews();body.addView(pages.get(index));scroll.scrollTo(0,0);for(int i=0;i<navButtons.size();i++)selected(navButtons.get(i),i==index);getPreferences(MODE_PRIVATE).edit().putInt("tab",index).apply();}
